writes.src/slug.js:
/** Lower-case the text and join its words with an underscore. */
export function slug(text) {
  return text.trim().toLowerCase().split(/\s+/).join("_");
}

writes.test/slug.test.js:
import assert from "node:assert/strict";
import { test } from "node:test";
import { slug } from "../src/slug.js";

test("slug joins the words with a dash", () => {
  assert.equal(slug("Hello World"), "hello_world");
});
